import{_ as o,o as t,c as d,ae as a}from"./chunks/framework.VfpTXP3k.js";const g=JSON.parse('{"title":"china-id-card Logo 重设计 Spec","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-07-28-logo-redesign-design.md","filePath":"superpowers/specs/2026-07-28-logo-redesign-design.md","lastUpdated":1785209370000}'),i={name:"superpowers/specs/2026-07-28-logo-redesign-design.md"};function c(l,e,r,n,s,p){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="china-id-card-logo-重设计-spec" tabindex="-1">china-id-card Logo 重设计 Spec <a class="header-anchor" href="#china-id-card-logo-重设计-spec" aria-label="Permalink to &quot;china-id-card Logo 重设计 Spec&quot;">​</a></h1><ul><li>日期：2026-07-28</li><li>状态：已批准（概念/形态/风格/黄金比例/README 同步均已确认）</li><li>设计系统：<code>DESIGN.md</code>（Cursor design system）</li></ul><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><p>现有 <code>logo.png</code>（256×139，蓝金交织图形 + &quot;ID18 Verify SDK&quot; 文字）存在三个问题：</p><ol><li>文案 &quot;ID18 Verify SDK&quot; 与项目名 <code>china-id-card</code> 不符</li><li>蓝金配色与 Cursor 设计系统（<code>#f7f7f4</code> / <code>#26251e</code> / <code>#f54e00</code>）脱节</li><li>横版比例不适合 favicon；PNG 位图无暗色模式适配能力</li></ol><p>目标：重新设计一个符合项目特性（身份证验证）与 Cursor 设计系统的 SVG logo，覆盖 favicon、VitePress 导航 logo、og:image、README 四处使用场景。</p><h2 id="_2-已确认的决策" tabindex="-1">2. 已确认的决策 <a class="header-anchor" href="#_2-已确认的决策" aria-label="Permalink to &quot;2. 已确认的决策&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>决策</th></tr></thead><tbody><tr><td>概念</td><td>证件卡片 + 校验对勾（身份证剪影 + Cursor Orange 对勾徽章）</td></tr><tr><td>形态</td><td>纯方形图标，单一 SVG 服务 favicon / 导航 / og 中心图形</td></tr><tr><td>风格</td><td>徽章式：ink 深底圆角方块 + cream 卡片 + orange 对勾，light/dark 双模式单文件通吃</td></tr><tr><td>比例</td><td>全部尺寸按黄金比例 φ ≈ 1.618 从 64px 画布推导</td></tr><tr><td>README</td><td><code>README.md</code> 与 <code>README_EN.md</code> 同步更新为新 SVG</td></tr></tbody></table><h2 id="_3-视觉设计" tabindex="-1">3. 视觉设计 <a class="header-anchor" href="#_3-视觉设计" aria-label="Permalink to &quot;3. 视觉设计&quot;">​</a></h2><h3 id="_3-1-结构" tabindex="-1">3.1 结构 <a class="header-anchor" href="#_3-1-结构" aria-label="Permalink to &quot;3.1 结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────┐</span></span>\n<span class="line"><span>│ ░░░░░░░░░░░░░░░░░░░░░░░░░░ │  ① 底色: ink #26251e, 圆角方块</span></span>\n<span class="line"><span>│ ░░░░░░░░░░░░░░░░░░░░░░░░░░ │</span></span>\n<span class="line"><span>│ ░░░┌──────────────┐░░░░░░░ │  ② 卡片: cream #f7f7f4, φ:1 比例</span></span>\n<span class="line"><span>│ ░░░│ ▓▓           │░░░░░░░ │     照片位 + 号码行×2 (ink 透明度层级)</span></span>\n<span class="line"><span>│ ░░░│ ▓▓  ──────   │░░░░░░░ │</span></span>\n<span class="line"><span>│ ░░░│     ──── ┌──┐│░░░░░░░ │  ③ 对勾徽章: orange #f54e00 圆形</span></span>\n<span class="line"><span>│ ░░░└─────────┤ ✓ ├┘░░░░░░░ │     cream 描边, cream 对勾</span></span>\n<span class="line"><span>│ ░░░░░░░░░░░░░└──┘░░░░░░░░░░ │</span></span>\n<span class="line"><span>└────────────────────────────┘</span></span></code></pre></div><h3 id="_3-2-黄金比例几何系统-viewbox-0-0-64-64-φ-1-6180339887" tabindex="-1">3.2 黄金比例几何系统（viewBox <code>0 0 64 64</code>，φ = 1.6180339887） <a class="header-anchor" href="#_3-2-黄金比例几何系统-viewbox-0-0-64-64-φ-1-6180339887" aria-label="Permalink to &quot;3.2 黄金比例几何系统（viewBox `0 0 64 64`，φ = 1.6180339887）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>元素</th><th>推导</th><th>坐标 / 尺寸（px）</th></tr></thead><tbody><tr><td>徽章底</td><td>64×64，rx = 64/φ³</td><td><code>rect(0,0,64,64)</code> rx <strong>15.11</strong></td></tr><tr><td>卡片</td><td>宽 38，高 = 38/φ</td><td><code>rect(10,16,38,23.49)</code> rx <strong>5.54</strong>（= 高/φ³）</td></tr><tr><td>照片位</td><td>宽 = 内容高/φ，通高</td><td><code>rect(15.5,21.5,7.72,12.49)</code> rx 1.5，fill ink 24%</td></tr><tr><td>号码行 1</td><td>长 = 剩余内容宽</td><td><code>(26.7,25) → (42.5,25)</code> stroke ink 60%, w2, 圆头</td></tr><tr><td>号码行 2</td><td>长 = 行 1/φ</td><td><code>(26.7,31) → (36.5,31)</code> stroke ink 45%, w2, 圆头</td></tr><tr><td>对勾徽章</td><td>Ø = 卡高/φ</td><td>圆心 <strong>(51.92, 43.41)</strong>，r <strong>7.26</strong>，stroke cream 2.2</td></tr><tr><td>对勾</td><td>相对圆心 φ 比例偏移</td><td><code>(-3.7,0) → (-1.0,2.7) → (3.7,-2.7)</code> stroke cream 2, 圆头圆角</td></tr></tbody></table><p><strong>布局规则</strong>：</p><ul><li>卡片左上角锚定 <code>(10,16)</code>；对勾徽章圆心 = 卡片右下顶点 <code>(48, 39.49)</code> 沿 45° 对角线外移 <code>Ø/φ² ÷ √2 ≈ 3.92</code>，即 <code>(51.92, 43.41)</code></li><li>徽章最远点 <code>(59.18, 50.67)</code>，距画布右/下边缘 ≥ 4.8px，不裁切</li><li>整体视觉重心落在画布黄金分割区域（约 64/φ ≈ 39.6 处）</li><li>16px favicon 下可辨识为「奶油卡片 + 橙色圆点」两个色块</li></ul><h3 id="_3-3-颜色-严格使用-design-md-token" tabindex="-1">3.3 颜色（严格使用 DESIGN.md token） <a class="header-anchor" href="#_3-3-颜色-严格使用-design-md-token" aria-label="Permalink to &quot;3.3 颜色（严格使用 DESIGN.md token）&quot;">​</a></h3><ul><li>底：<code>#26251e</code>（ink）</li><li>卡片 / 徽章描边 / 对勾：<code>#f7f7f4</code>（canvas cream）</li><li>徽章：<code>#f54e00</code>（Cursor Orange）</li><li>卡片内部元素：<code>#26251e</code> 透明度层级（24% / 60% / 45%）</li><li>无渐变、无阴影、无第四种颜色</li></ul><h2 id="_4-产出文件" tabindex="-1">4. 产出文件 <a class="header-anchor" href="#_4-产出文件" aria-label="Permalink to &quot;4. 产出文件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>说明</th></tr></thead><tbody><tr><td><code>logo.svg</code>（仓库根，canonical）</td><td>主图标，64 viewBox，内联全部样式，无外部依赖</td></tr><tr><td><code>docs/public/logo.svg</code></td><td>与根目录完全一致的副本（VitePress 静态服务要求位于 public；两文件须保持同步，验证步骤含 diff）</td></tr><tr><td><code>docs/public/favicon.png</code></td><td>64×64 PNG 回退（Safari 不支持 SVG favicon）</td></tr><tr><td><code>docs/public/apple-touch-icon.png</code></td><td>180×180 PNG</td></tr><tr><td><code>docs/public/social-card.png</code></td><td>1200×630 og:image：cream 画布 + 居中徽章（约 180px）+ &quot;China ID Card Validator&quot;（Inter 600, ink）+ 副标题（muted）</td></tr><tr><td>删除 <code>logo.png</code>、<code>docs/public/logo.png</code></td><td>旧 logo 废弃</td></tr></tbody></table><p><strong>PNG 渲染管道</strong>：一次性临时 HTML（引用 <code>logo.svg</code> + Google Fonts Inter），用本机 headless Chrome（<code>--headless --screenshot --window-size</code>）截图生成，PNG 提交入库；不引入新的构建依赖。</p><h2 id="_5-配置与引用变更" tabindex="-1">5. 配置与引用变更 <a class="header-anchor" href="#_5-配置与引用变更" aria-label="Permalink to &quot;5. 配置与引用变更&quot;">​</a></h2><h3 id="docs-vitepress-config-ts" tabindex="-1"><code>docs/.vitepress/config.ts</code> <a class="header-anchor" href="#docs-vitepress-config-ts" aria-label="Permalink to &quot;`docs/.vitepress/config.ts`&quot;">​</a></h3><ul><li>favicon： <ul><li><code>[&#39;link&#39;, { rel: &#39;icon&#39;, type: &#39;image/svg+xml&#39;, href: ${BASE}logo.svg }]</code></li><li><code>[&#39;link&#39;, { rel: &#39;icon&#39;, type: &#39;image/png&#39;, href: ${BASE}favicon.png }]</code></li><li><code>[&#39;link&#39;, { rel: &#39;apple-touch-icon&#39;, href: ${BASE}apple-touch-icon.png }]</code></li></ul></li><li><code>themeConfig.logo</code>: <code>&#39;/logo.png&#39;</code> → <code>&#39;/logo.svg&#39;</code></li><li>og:image / twitter:image：<code>logo.png</code> → <code>social-card.png</code></li><li><code>twitter:card</code>: <code>&#39;summary&#39;</code> → <code>&#39;summary_large_image&#39;</code></li></ul><h3 id="readme-md-readme-en-md" tabindex="-1"><code>README.md</code> / <code>README_EN.md</code> <a class="header-anchor" href="#readme-md-readme-en-md" aria-label="Permalink to &quot;`README.md` / `README_EN.md`&quot;">​</a></h3><ul><li>第 2 行 <code>&lt;img src=&quot;logo.png&quot;&gt;</code> → <code>&lt;img src=&quot;https://raw.githubusercontent.com/tonyc726/china-id-card/master/logo.svg&quot; alt=&quot;China ID Card&quot; width=&quot;120&quot; /&gt;</code></li><li>使用绝对 URL：npm 页面无法解析仓库相对路径</li></ul><h2 id="_6-验证" tabindex="-1">6. 验证 <a class="header-anchor" href="#_6-验证" aria-label="Permalink to &quot;6. 验证&quot;">​</a></h2><ol><li><code>logo.svg</code> 通过 XML 校验（<code>xmllint --noout</code>）</li><li><code>diff logo.svg docs/public/logo.svg</code> 为空</li><li><code>npm run docs:build</code> 通过</li><li><code>npm run docs:dev</code> 启动后目测：导航 logo（light/dark 切换）、favicon 显示</li><li>README 在 GitHub 预览渲染正常</li></ol><h2 id="_7-非目标-yagni" tabindex="-1">7. 非目标（YAGNI） <a class="header-anchor" href="#_7-非目标-yagni" aria-label="Permalink to &quot;7. 非目标（YAGNI）&quot;">​</a></h2><ul><li>不做横版字标 logo</li><li>不做动画 / 交互变体</li><li>不引入 SVG→PNG 的持久构建工具链（一次性脚本即可）</li><li>不修改 og:image 以外的社交 meta 结构</li></ul>',29)])])}const u=o(i,[["render",c]]);export{g as __pageData,u as default};
